const net = require('net');
function tryBind(host, port) {
  return new Promise((res) => {
    const s = net.createServer();
    s.on('error', e => res(`${host}:${port} -> FAIL ${e.code} ${e.message}`));
    s.listen(port, host, () => { const a = s.address(); s.close(() => res(`${host}:${port} -> OK (got ${a.port})`)); });
  });
}
(async () => {
  for (const [h,p] of [['127.0.0.1',0],['localhost',0],['::1',0],['127.0.0.1',54545],[undefined,0]]) {
    console.log(await tryBind(h,p));
  }
})();
EOF
